/**
 * MultiCamStrategyEngine — Strategy Databases for 6 CAM Systems
 *
 * Contains machining strategy knowledge for:
 *   - Fusion 360 (Autodesk)
 *   - Mastercam (CNC Software / Sandvik)
 *   - ESPRIT (Hexagon)
 *   - Siemens NX CAM
 *   - GibbsCAM (3D Systems)
 *   - SurfCAM (Hexagon)
 *
 * Each CAM system's strategies are normalized into a common schema
 * compatible with HyperMillStrategyEngine and CamKnowledgePortabilityEngine.
 *
 * Generated by /pdf-learn forge-triple pipeline
 */

// ============================================================================
// TYPES
// ============================================================================

export type MultiCamSource =
  | "fusion360"
  | "mastercam"
  | "esprit"
  | "siemensnx"
  | "gibbscam"
  | "surfcam"
  | "solidcam";

export type CamGeometryType =
  | "pocket_2d"
  | "contour_2d"
  | "face"
  | "slot"
  | "chamfer"
  | "freeform_3d"
  | "steep_wall"
  | "flat_area"
  | "groove"
  | "rib"
  | "corner"
  | "turning_external"
  | "turning_internal"
  | "turning_groove"
  | "thread"
  | "hole"
  | "bore"
  | "impeller_blade"
  | "port_inlet"
  | "ruled_surface"
  | "trimming_edge"
  | "undercut"
  | "turbine_blade";

export type CamOperationGoal =
  | "roughing"
  | "finishing"
  | "semi_finishing"
  | "rest_machining"
  | "drilling"
  | "adaptive_clearing"
  | "deburring";

export interface CamStrategyInput {
  camSystem: MultiCamSource;
  geometryType: CamGeometryType;
  operationGoal: CamOperationGoal;
  materialGroup?: string; // ISO P/M/K/N/S/H
  toolDiameterMm?: number;
  wallAngleDeg?: number;
  hasPreviousRoughing?: boolean;
  axisCount?: 3 | 4 | 5;
}

export interface CamStrategyResult {
  strategyName: string;
  nativeCycleName: string; // CAM-system-specific cycle identifier
  camSystem: MultiCamSource;
  description: string;
  suggestedStepdown: number | null; // factor of tool diameter
  suggestedStepover: number | null; // factor of tool diameter
  cuttingMode: "climb" | "conventional" | "zigzag";
  warnings: string[];
  confidence: number;
  equivalentIntents: string[]; // CamIntent values for portability
  source: string;
}

export interface MultiCamStats {
  totalStrategies: number;
  bySystem: Record<MultiCamSource, number>;
  calculations: number;
}

// ============================================================================
// STRATEGY ENTRY (internal)
// ============================================================================

interface StrategyEntry {
  nativeCycle: string;
  description: string;
  stepdownFactor: number | null;
  stepoverFactor: number | null;
  cuttingMode: "climb" | "conventional" | "zigzag";
  suitableFor: { geometry: CamGeometryType[]; goal: CamOperationGoal[] };
  priority: number;
  equivalentIntents: string[];
  materialNotes?: Record<string, string>; // ISO group → note
}

