// ============================================================================
// SYSTEM MAP
// ============================================================================

const STRATEGY_MAP: Record<MultiCamSource, StrategyEntry[]> = {
  fusion360: FUSION360_STRATEGIES,
  mastercam: MASTERCAM_STRATEGIES,
  esprit: ESPRIT_STRATEGIES,
  siemensnx: SIEMENSNX_STRATEGIES,
  gibbscam: GIBBSCAM_STRATEGIES,
  surfcam: SURFCAM_STRATEGIES,
  solidcam: SOLIDCAM_STRATEGIES,
};

/** Flagship adaptive/dynamic strategy name per CAM system */
const FLAGSHIP_STRATEGIES: Record<MultiCamSource, string> = {
  fusion360: "Adaptive Clearing",
  mastercam: "Dynamic Mill",
  esprit: "ProfitMilling",
  siemensnx: "Volume Based Machining",
  gibbscam: "VoluMill",
  surfcam: "TrueMill",
  solidcam: "iMachining 3D",
};

// ============================================================================
// ENGINE CLASS
// ============================================================================

export class MultiCamStrategyEngine {
  private calculations = 0;

  /**
   * Recommend the best strategy for a given CAM system, geometry, and goal.
   */
  recommend(input: CamStrategyInput): CamStrategyResult {
    this.calculations++;
    const strategies = STRATEGY_MAP[input.camSystem];
    if (!strategies) {
      return this.notFound(input, `Unknown CAM system: ${input.camSystem}`);
    }

    // Filter by geometry + goal
    const candidates = strategies.filter(
      (s) =>
        s.suitableFor.geometry.includes(input.geometryType) &&
        s.suitableFor.goal.includes(input.operationGoal)
    );

    if (candidates.length === 0) {
      return this.notFound(input, `No strategy for ${input.geometryType}/${input.operationGoal} in ${input.camSystem}`);
    }

    // Sort by priority (highest first)
    candidates.sort((a, b) => b.priority - a.priority);
    const best = candidates[0];

    // Build warnings
    const warnings: string[] = [];

    // Material-specific warnings
    if (input.materialGroup && best.materialNotes?.[input.materialGroup]) {
      // Material note is informational, not a warning
    }
    if (input.materialGroup === "S" && input.operationGoal === "roughing") {
      warnings.push("Superalloy roughing: reduce speed 30-40%, use through-spindle coolant if available");
    }
    if (input.materialGroup === "H" && best.stepdownFactor && best.stepdownFactor > 1.5) {
      warnings.push("Hardened material: reduce depth of cut to 50% of suggested value");
    }
    if (input.axisCount && input.axisCount < 5 && best.equivalentIntents.some((i) => i.startsWith("5axis"))) {
      warnings.push(`Strategy requires 5-axis but machine has ${input.axisCount} axes`);
    }

    // Stepdown/stepover adjustments by material
    let stepdown = best.stepdownFactor;
    let stepover = best.stepoverFactor;
    if (input.materialGroup === "S" || input.materialGroup === "H") {
      if (stepdown !== null) stepdown = Math.min(stepdown, 1.0);
      if (stepover !== null) stepover = Math.min(stepover, stepover * 0.7);
    }

    return {
      strategyName: best.nativeCycle,
      nativeCycleName: best.nativeCycle,
      camSystem: input.camSystem,
      description: best.description,
      suggestedStepdown: stepdown,
      suggestedStepover: stepover,
      cuttingMode: best.cuttingMode,
      warnings,
      confidence: this.calcConfidence(best, input),
      equivalentIntents: best.equivalentIntents,
      source: `multicam:${input.camSystem}`,
    };
  }

  /**
   * List all strategies for a given CAM system.
   */
  listStrategies(camSystem: MultiCamSource): CamStrategyResult[] {
    const strategies = STRATEGY_MAP[camSystem];
    if (!strategies) return [];
    return strategies.map((s) => ({
      strategyName: s.nativeCycle,
      nativeCycleName: s.nativeCycle,
      camSystem,
      description: s.description,
      suggestedStepdown: s.stepdownFactor,
      suggestedStepover: s.stepoverFactor,
      cuttingMode: s.cuttingMode,
      warnings: [],
      confidence: 1.0,
      equivalentIntents: s.equivalentIntents,
      source: `multicam:${camSystem}`,
    }));
  }

  /**
   * Get the flagship adaptive/dynamic strategy for a CAM system.
   */
  getFlagship(camSystem: MultiCamSource): CamStrategyResult | null {
    const name = FLAGSHIP_STRATEGIES[camSystem];
    if (!name) return null;
    const strategies = STRATEGY_MAP[camSystem];
    const entry = strategies?.find((s) => s.nativeCycle === name);
    if (!entry) return null;
    return {
      strategyName: entry.nativeCycle,
      nativeCycleName: entry.nativeCycle,
      camSystem,
      description: entry.description,
      suggestedStepdown: entry.stepdownFactor,
      suggestedStepover: entry.stepoverFactor,
      cuttingMode: entry.cuttingMode,
      warnings: [],
      confidence: 1.0,
      equivalentIntents: entry.equivalentIntents,
      source: `multicam:${camSystem}`,
    };
  }

  /**
   * Compare equivalent strategies across all CAM systems for a given geometry/goal.
   */
  compareAcrossSystems(
    geometryType: CamGeometryType,
    operationGoal: CamOperationGoal
  ): Record<MultiCamSource, CamStrategyResult | null> {
    const result: Record<string, CamStrategyResult | null> = {};
    for (const sys of Object.keys(STRATEGY_MAP) as MultiCamSource[]) {
      const rec = this.recommend({
        camSystem: sys,
        geometryType,
        operationGoal,
      });
      result[sys] = rec.confidence > 0 ? rec : null;
    }
    return result as Record<MultiCamSource, CamStrategyResult | null>;
  }

  /**
   * Find which intents a given CAM strategy maps to (for portability).
   */
  getPortabilityIntents(
    camSystem: MultiCamSource,
    nativeCycleName: string
  ): string[] {
    const strategies = STRATEGY_MAP[camSystem];
    if (!strategies) return [];
    const entry = strategies.find((s) => s.nativeCycle === nativeCycleName);
    return entry?.equivalentIntents ?? [];
  }

  /**
   * Get stats about the strategy database.
   */
  stats(): MultiCamStats {
    const bySystem: Record<string, number> = {};
    let total = 0;
    for (const [sys, strats] of Object.entries(STRATEGY_MAP)) {
      bySystem[sys] = strats.length;
      total += strats.length;
    }
    return {
      totalStrategies: total,
      bySystem: bySystem as Record<MultiCamSource, number>,
      calculations: this.calculations,
    };
  }

  /**
   * List all supported CAM systems.
   */
  listSystems(): MultiCamSource[] {
    return Object.keys(STRATEGY_MAP) as MultiCamSource[];
  }

  // ── Private ─────────────────────────────────────────────────────────────

  private calcConfidence(entry: StrategyEntry, input: CamStrategyInput): number {
    let c = 0.8;
    if (input.materialGroup) c += 0.05;
    if (input.toolDiameterMm) c += 0.05;
    if (entry.priority >= 12) c += 0.05;
    if (entry.materialNotes && input.materialGroup && entry.materialNotes[input.materialGroup]) c += 0.05;
    return Math.min(c, 1.0);
  }

  private notFound(input: CamStrategyInput, msg: string): CamStrategyResult {
    return {
      strategyName: "none",
      nativeCycleName: "none",
      camSystem: input.camSystem,
      description: msg,
      suggestedStepdown: null,
      suggestedStepover: null,
      cuttingMode: "climb",
      warnings: [msg],
      confidence: 0,
      equivalentIntents: [],
      source: `multicam:${input.camSystem}`,
    };
  }
}

// ── Singleton ───────────────────────────────────────────────────────────────
export const multiCamStrategyEngine = new MultiCamStrategyEngine();
